mapper.delete:
update T_MDM_STOCK_UP_PLAN
set IS_DELETE = 1
where IS_DELETE = 0
and YEAR = #{year}
and MONTH = #{month}

    and (FACTORY_CODE,PRODUCT_CODE) in(
    select tmpi.FACTORY_CODE,tmpi.PRODUCT_CODE from T_MDM_MATERIAL_INFO tmpi
    where tmpi.IS_DELETE = 0
    and tmpi.TIRE_TYPE = #{tireType}
    )

mapper.select:
SELECT msup.ID, msup.FACTORY_CODE, msup.YEAR, msup.MONTH, msup.PRODUCT_CODE, msup.PRODUCT_DESC, empc.EMBRYO_CODE, mmmr.MOULD_NO, msup.LOCATION_TYPE, msup.AVERAGE_TYPE, msup.AVERAGE_VALUE, msup.FACTOR, msup.STOCK_QTY, msup.STOCK_TIME, msup.STOCKOIST, msup.APPROVE_TIME, msup.APPROVER, msup.IS_DELETE, msup.CREATE_BY, msup.CREATE_TIME, msup.UPDATE_BY, msup.UPDATE_TIME FROM T_MDM_STOCK_UP_PLAN msup LEFT JOIN (SELECT tmpc.FACTORY_CODE, tmpc.PRODUCT_CODE, GROUP_CONCAT(tmpc.EMBRYO_CODE) AS EMBRYO_CODE FROM t_mdm_product_construction tmpc WHERE tmpc.IS_DELETE = 0
AND tmpc.FACTORY_CODE = #{factoryCode}
GROUP BY tmpc.FACTORY_CODE,tmpc.PRODUCT_CODE ) empc ON msup.FACTORY_CODE = empc.FACTORY_CODE AND msup.PRODUCT_CODE = empc.PRODUCT_CODE LEFT JOIN (SELECT mpmr.FACTORY_CODE, mpmr.PRODUCT_CODE, GROUP_CONCAT( DISTINCT(tmmi.MOULD_NO) ) AS MOULD_NO FROM t_mdm_product_model_relation mpmr LEFT JOIN T_MDM_MOULD_INFO tmmi ON tmmi.MOULD_CODE = mpmr.MOULD_CODE AND tmmi.FACTORY_CODE = mpmr.FACTORY_CODE WHERE 1=1
AND mpmr.FACTORY_CODE = #{factoryCode}
GROUP BY mpmr.FACTORY_CODE, mpmr.PRODUCT_CODE ) mmmr ON msup.FACTORY_CODE = mmmr.FACTORY_CODE AND msup.PRODUCT_CODE = mmmr.PRODUCT_CODE WHERE msup.IS_DELETE = 0
AND msup.FACTORY_CODE = #{factoryCode}
AND msup.YEAR = #{year}
AND msup.MONTH = #{month}
AND msup.PRODUCT_CODE = #{productCode}
AND msup.PRODUCT_DESC = #{productDesc}
AND msup.LOCATION_TYPE = #{locationType}
AND msup.AVERAGE_TYPE = #{averageType}
AND msup.AVERAGE_VALUE = #{averageValue}
AND msup.FACTOR = #{factor}
AND msup.STOCK_QTY = #{stockQty}
AND msup.STOCK_TIME = #{stockTime}
AND msup.STOCKOIST = #{stockoist}
AND msup.APPROVE_TIME = #{approveTime}
AND msup.APPROVER = #{approver}
AND mmmr.MOULD_NO LIKE #{mouldNo} || '%'
AND empc.EMBRYO_CODE LIKE #{embryoCode} || '%'

SELECT msup.AVERAGE_TYPE
  FROM t_mdm_stock_up_plan msup
 WHERE msup.IS_DELETE = 0
   AND msup.AVERAGE_TYPE IS NOT NULL
   AND msup.FACTORY_CODE = #{factoryCode}
   AND msup.YEAR = #{year}
   AND msup.MONTH = #{month}
 ORDER BY msup.ID LIMIT 1;

SELECT COUNT(1)
  FROM t_mdm_stock_up_plan msup
 WHERE msup.IS_DELETE = 0
   AND msup.FACTORY_CODE = #{factoryCode}
   AND msup.YEAR = #{year}
   AND msup.MONTH = #{month}
   AND msup.LOCATION_TYPE = #{locationType}
   AND msup.PRODUCT_CODE = #{productCode}
